CREATE TABLE IF NOT EXISTS japanese_dictionary (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    hiragana TEXT NOT NULL,
    kanji TEXT NULL,
    han_viet TEXT NULL,
    meaning TEXT NOT NULL,
    level TEXT NOT NULL CHECK (level IN ('N5', 'N4', 'N3', 'N2', 'N1')),
    word_type TEXT NULL,
    example_ja TEXT NULL,
    example_vi TEXT NULL
);
CREATE UNIQUE INDEX IF NOT EXISTS idx_japanese_dictionary_unique ON japanese_dictionary (hiragana, IFNULL(kanji, ''));
CREATE INDEX IF NOT EXISTS idx_japanese_dictionary_hiragana ON japanese_dictionary (hiragana);
CREATE INDEX IF NOT EXISTS idx_japanese_dictionary_kanji ON japanese_dictionary (kanji);
CREATE INDEX IF NOT EXISTS idx_japanese_dictionary_han_viet ON japanese_dictionary (han_viet);
CREATE INDEX IF NOT EXISTS idx_japanese_dictionary_level ON japanese_dictionary (level);

CREATE TABLE IF NOT EXISTS japanese_kanji (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    character TEXT NOT NULL,
    han_viet TEXT NULL,
    on_reading TEXT NULL,
    kun_reading TEXT NULL,
    meaning TEXT NULL,
    strokes INTEGER NULL,
    level TEXT NULL CHECK (level IS NULL OR level IN ('N5', 'N4', 'N3', 'N2', 'N1'))
);
CREATE UNIQUE INDEX IF NOT EXISTS idx_japanese_kanji_character ON japanese_kanji (character);
CREATE INDEX IF NOT EXISTS idx_japanese_kanji_han_viet ON japanese_kanji (han_viet);

BEGIN TRANSACTION;
COMMIT;
